-- WrenchMatch demo schema, migration 0001 (SQLite, STRICT tables).
--
-- Conventions
--   * ids are TEXT UUIDs generated by the application (crypto.randomUUID()).
--   * timestamps are UTC ISO-8601 strings 'YYYY-MM-DDTHH:MM:SS.sssZ' (the format of
--     JavaScript's Date#toISOString) so they compare correctly as text.
--   * calendar dates are 'YYYY-MM-DD'. Booleans are INTEGER 0/1.
--   * money is INTEGER cents plus an ISO-4217 currency code (USD only for the pilot).
--   * rules that must hold even if application code is wrong are enforced here with
--     CHECK constraints, unique indexes and triggers. Authorization (who may read or
--     change a row) is enforced in the server data-access layer; SQLite has no RLS.

-- ---------------------------------------------------------------------------------
-- Accounts and sessions
-- ---------------------------------------------------------------------------------

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL COLLATE NOCASE UNIQUE
    CHECK (length(email) BETWEEN 3 AND 254 AND email LIKE '%_@_%'),
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('customer', 'mechanic', 'admin')),
  display_name TEXT NOT NULL CHECK (length(trim(display_name)) BETWEEN 1 AND 80),
  email_verified_at TEXT,
  is_demo_account INTEGER NOT NULL DEFAULT 0 CHECK (is_demo_account IN (0, 1)),
  disabled_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- A role can never be changed after the account exists (blocks privilege escalation).
CREATE TRIGGER users_role_is_immutable
BEFORE UPDATE OF role ON users
WHEN NEW.role IS NOT OLD.role
BEGIN
  SELECT RAISE(ABORT, 'role_immutable');
END;

-- Session tokens are random; only their SHA-256 hex digest is stored.
CREATE TABLE sessions (
  id TEXT PRIMARY KEY CHECK (length(id) = 64),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  expires_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX sessions_expires_idx ON sessions(expires_at);

-- Fixed-window counters for login/signup/submission rate limits.
CREATE TABLE rate_limits (
  bucket_key TEXT PRIMARY KEY,
  window_started_at TEXT NOT NULL,
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0)
) STRICT;

-- ---------------------------------------------------------------------------------
-- Private files (stored on local disk outside public/, streamed only after an
-- authorization check). Images are always re-encoded with metadata stripped.
-- ---------------------------------------------------------------------------------

CREATE TABLE files (
  id TEXT PRIMARY KEY,
  owner_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  purpose TEXT NOT NULL
    CHECK (purpose IN ('request_photo', 'request_video', 'mechanic_profile_photo', 'mechanic_document')),
  storage_key TEXT NOT NULL UNIQUE
    CHECK (length(storage_key) BETWEEN 5 AND 200
      AND storage_key NOT LIKE '%..%'
      AND storage_key NOT LIKE '/%'
      AND storage_key NOT LIKE '%\%'),
  mime_type TEXT NOT NULL
    CHECK (mime_type IN ('image/jpeg', 'image/png', 'image/webp',
                         'video/mp4', 'video/quicktime', 'video/webm',
                         'application/pdf')),
  size_bytes INTEGER NOT NULL CHECK (size_bytes > 0),
  width INTEGER CHECK (width IS NULL OR width > 0),
  height INTEGER CHECK (height IS NULL OR height > 0),
  sha256 TEXT NOT NULL CHECK (length(sha256) = 64),
  metadata_stripped INTEGER NOT NULL DEFAULT 0 CHECK (metadata_stripped IN (0, 1)),
  original_name TEXT CHECK (original_name IS NULL OR length(original_name) <= 200),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (
    (purpose IN ('request_photo', 'mechanic_profile_photo')
       AND mime_type IN ('image/jpeg', 'image/png', 'image/webp'))
    OR (purpose = 'request_video'
       AND mime_type IN ('video/mp4', 'video/quicktime', 'video/webm'))
    OR (purpose = 'mechanic_document'
       AND mime_type IN ('image/jpeg', 'image/png', 'image/webp', 'application/pdf'))
  ),
  -- every stored image must have had its EXIF/GPS metadata removed
  CHECK (mime_type NOT LIKE 'image/%' OR metadata_stripped = 1)
) STRICT;
CREATE INDEX files_owner_idx ON files(owner_user_id);

-- ---------------------------------------------------------------------------------
-- Reference data: service categories (seeded below) and the configurable pilot area
-- ---------------------------------------------------------------------------------

CREATE TABLE service_categories (
  id TEXT PRIMARY KEY CHECK (id GLOB '[a-z]*' AND id NOT GLOB '*[^a-z_]*'),
  name TEXT NOT NULL UNIQUE,
  short_description TEXT NOT NULL,
  customer_notice TEXT,
  safety_sensitive INTEGER NOT NULL DEFAULT 0 CHECK (safety_sensitive IN (0, 1)),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  sort_order INTEGER NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- Approximate ZIP centroids (no paid geocoder). Matching uses these points.
CREATE TABLE zip_centroids (
  zip TEXT PRIMARY KEY CHECK (zip GLOB '[0-9][0-9][0-9][0-9][0-9]'),
  city TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state GLOB '[A-Z][A-Z]'),
  lat REAL NOT NULL CHECK (lat BETWEEN -90 AND 90),
  lng REAL NOT NULL CHECK (lng BETWEEN -180 AND 180),
  time_zone TEXT NOT NULL CHECK (length(time_zone) BETWEEN 3 AND 64),
  source TEXT NOT NULL
) STRICT;

CREATE TABLE pilot_zips (
  zip TEXT PRIMARY KEY REFERENCES zip_centroids(zip),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  metro_label TEXT NOT NULL CHECK (length(trim(metro_label)) BETWEEN 1 AND 80),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- ---------------------------------------------------------------------------------
-- Mechanics. Public/display fields live in mechanic_profiles; contact details,
-- legal/business name, exact garage address and policy numbers live in
-- mechanic_private and are never selected for other users before a confirmed booking.
-- ---------------------------------------------------------------------------------

CREATE TABLE mechanic_profiles (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  display_name TEXT NOT NULL CHECK (length(trim(display_name)) BETWEEN 1 AND 60),
  bio TEXT CHECK (bio IS NULL OR length(bio) <= 1000),
  years_experience INTEGER NOT NULL CHECK (years_experience BETWEEN 0 AND 60),
  certifications TEXT CHECK (certifications IS NULL OR length(certifications) <= 500),
  service_mode TEXT NOT NULL CHECK (service_mode IN ('mobile', 'garage', 'both')),
  travel_radius_miles INTEGER NOT NULL CHECK (travel_radius_miles BETWEEN 1 AND 100),
  base_zip TEXT NOT NULL REFERENCES zip_centroids(zip),
  -- approximate base point (ZIP centroid); exact garage address is private text only
  base_lat REAL NOT NULL CHECK (base_lat BETWEEN -90 AND 90),
  base_lng REAL NOT NULL CHECK (base_lng BETWEEN -180 AND 180),
  services_all_makes INTEGER NOT NULL DEFAULT 0 CHECK (services_all_makes IN (0, 1)),
  insurance_provider TEXT CHECK (insurance_provider IS NULL OR length(insurance_provider) <= 120),
  insurance_expires_on TEXT
    CHECK (insurance_expires_on IS NULL
      OR insurance_expires_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  accepting_jobs INTEGER NOT NULL DEFAULT 1 CHECK (accepting_jobs IN (0, 1)),
  profile_photo_file_id TEXT REFERENCES files(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'applied'
    CHECK (status IN ('applied', 'under_review', 'approved', 'rejected', 'suspended')),
  status_reason TEXT CHECK (status_reason IS NULL OR length(status_reason) <= 500),
  status_changed_at TEXT,
  status_changed_by TEXT REFERENCES users(id),
  approved_at TEXT,
  submitted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  -- rejecting or suspending always records a reason
  CHECK (status NOT IN ('rejected', 'suspended')
    OR (status_reason IS NOT NULL AND length(trim(status_reason)) >= 3))
) STRICT;
CREATE INDEX mechanic_profiles_status_idx ON mechanic_profiles(status);

CREATE TRIGGER mechanic_profiles_valid_status_transition
BEFORE UPDATE OF status ON mechanic_profiles
WHEN NEW.status IS NOT OLD.status
  AND (OLD.status || '>' || NEW.status) NOT IN (
    'applied>under_review', 'applied>approved', 'applied>rejected',
    'under_review>approved', 'under_review>rejected',
    'approved>suspended',
    'suspended>approved', 'suspended>rejected',
    'rejected>applied'
  )
BEGIN
  SELECT RAISE(ABORT, 'invalid_mechanic_status_transition');
END;

-- A mechanic cannot be approved without recorded insurance. (Expiry is checked by the
-- approval command against its injected clock, and again by matching.)
CREATE TRIGGER mechanic_profiles_approval_requires_insurance
BEFORE UPDATE OF status ON mechanic_profiles
WHEN NEW.status = 'approved' AND OLD.status IS NOT 'approved'
  AND (NEW.insurance_expires_on IS NULL OR NEW.insurance_provider IS NULL)
BEGIN
  SELECT RAISE(ABORT, 'insurance_required_for_approval');
END;

CREATE TABLE mechanic_private (
  user_id TEXT PRIMARY KEY REFERENCES mechanic_profiles(user_id) ON DELETE CASCADE,
  legal_name TEXT NOT NULL CHECK (length(trim(legal_name)) BETWEEN 1 AND 120),
  business_name TEXT CHECK (business_name IS NULL OR length(business_name) <= 120),
  phone TEXT NOT NULL CHECK (length(phone) BETWEEN 7 AND 32),
  contact_email TEXT NOT NULL CHECK (contact_email LIKE '%_@_%'),
  garage_address_line1 TEXT CHECK (garage_address_line1 IS NULL OR length(garage_address_line1) <= 200),
  garage_city TEXT,
  garage_state TEXT,
  garage_zip TEXT,
  insurance_policy_number TEXT CHECK (insurance_policy_number IS NULL OR length(insurance_policy_number) <= 80),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE mechanic_makes (
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id) ON DELETE CASCADE,
  make TEXT NOT NULL CHECK (length(make) BETWEEN 1 AND 40),
  PRIMARY KEY (mechanic_id, make)
) STRICT;

-- Categories a mechanic offers. Safety-sensitive categories (brake/suspension) only
-- count for matching once an admin sets safety_approved = 1.
CREATE TABLE mechanic_services (
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id) ON DELETE CASCADE,
  category_id TEXT NOT NULL REFERENCES service_categories(id),
  safety_approved INTEGER NOT NULL DEFAULT 0 CHECK (safety_approved IN (0, 1)),
  safety_approved_by TEXT REFERENCES users(id),
  safety_approved_at TEXT,
  PRIMARY KEY (mechanic_id, category_id)
) STRICT;

-- Weekly availability windows in the mechanic's local (pilot-area) time.
CREATE TABLE mechanic_availability (
  id TEXT PRIMARY KEY,
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id) ON DELETE CASCADE,
  weekday INTEGER NOT NULL CHECK (weekday BETWEEN 0 AND 6), -- 0 = Sunday
  start_minute INTEGER NOT NULL CHECK (start_minute BETWEEN 0 AND 1439),
  end_minute INTEGER NOT NULL CHECK (end_minute BETWEEN 1 AND 1440),
  CHECK (end_minute > start_minute)
) STRICT;
CREATE INDEX mechanic_availability_mechanic_idx ON mechanic_availability(mechanic_id, weekday);

CREATE TABLE mechanic_documents (
  id TEXT PRIMARY KEY,
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id) ON DELETE CASCADE,
  file_id TEXT NOT NULL UNIQUE REFERENCES files(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('id_document', 'insurance', 'certification', 'other')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'rejected')),
  expires_on TEXT
    CHECK (expires_on IS NULL OR expires_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  review_note TEXT CHECK (review_note IS NULL OR length(review_note) <= 500),
  reviewed_by TEXT REFERENCES users(id),
  reviewed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX mechanic_documents_mechanic_idx ON mechanic_documents(mechanic_id);

-- ---------------------------------------------------------------------------------
-- Repair requests. Coarse fields (area label, ZIP centroid) may be shown to matched
-- mechanics; request_private holds contact details and the exact address.
-- ---------------------------------------------------------------------------------

CREATE TABLE repair_requests (
  id TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'open', 'quoted', 'reserved', 'booked', 'expired', 'cancelled')),
  zip TEXT NOT NULL REFERENCES zip_centroids(zip),
  approx_lat REAL NOT NULL CHECK (approx_lat BETWEEN -90 AND 90),
  approx_lng REAL NOT NULL CHECK (approx_lng BETWEEN -180 AND 180),
  area_label TEXT NOT NULL CHECK (length(area_label) BETWEEN 3 AND 80),
  time_zone TEXT NOT NULL,
  vehicle_year INTEGER NOT NULL CHECK (vehicle_year BETWEEN 1960 AND 2100),
  vehicle_make TEXT NOT NULL CHECK (length(vehicle_make) BETWEEN 1 AND 40),
  vehicle_model TEXT NOT NULL CHECK (length(trim(vehicle_model)) BETWEEN 1 AND 60),
  mileage INTEGER NOT NULL CHECK (mileage BETWEEN 0 AND 2000000),
  category_id TEXT NOT NULL REFERENCES service_categories(id),
  description TEXT NOT NULL CHECK (length(trim(description)) BETWEEN 10 AND 2000),
  drivable INTEGER NOT NULL CHECK (drivable IN (0, 1)),
  preferred_date TEXT NOT NULL CHECK (preferred_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  preferred_window TEXT NOT NULL
    CHECK (preferred_window IN ('morning', 'afternoon', 'evening', 'flexible')),
  service_mode TEXT NOT NULL CHECK (service_mode IN ('mobile', 'garage', 'either')),
  max_garage_distance_miles INTEGER NOT NULL DEFAULT 15
    CHECK (max_garage_distance_miles BETWEEN 1 AND 100),
  matched_count INTEGER NOT NULL DEFAULT 0 CHECK (matched_count >= 0),
  submitted_at TEXT,
  expires_at TEXT,
  is_demo_fixture INTEGER NOT NULL DEFAULT 0 CHECK (is_demo_fixture IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (status = 'draft' OR (submitted_at IS NOT NULL AND expires_at IS NOT NULL))
) STRICT;
CREATE INDEX repair_requests_customer_idx ON repair_requests(customer_id, created_at);
CREATE INDEX repair_requests_status_idx ON repair_requests(status);

CREATE TRIGGER repair_requests_valid_status_transition
BEFORE UPDATE OF status ON repair_requests
WHEN NEW.status IS NOT OLD.status
  AND (OLD.status || '>' || NEW.status) NOT IN (
    'draft>open', 'draft>cancelled',
    'open>quoted', 'open>expired', 'open>cancelled',
    'quoted>open', 'quoted>reserved', 'quoted>expired', 'quoted>cancelled',
    'reserved>booked', 'reserved>cancelled'
  )
BEGIN
  SELECT RAISE(ABORT, 'invalid_request_transition');
END;

-- 'reserved' and 'booked' must be backed by the request's single booking row.
CREATE TRIGGER repair_requests_reserved_requires_booking
BEFORE UPDATE OF status ON repair_requests
WHEN NEW.status IN ('reserved', 'booked') AND NEW.status IS NOT OLD.status
  AND NOT EXISTS (
    SELECT 1 FROM bookings b
    WHERE b.request_id = NEW.id
      AND ((NEW.status = 'reserved' AND b.status = 'pending_payment')
        OR (NEW.status = 'booked' AND b.status IN ('confirmed', 'in_progress', 'completed', 'disputed')))
  )
BEGIN
  SELECT RAISE(ABORT, 'request_status_requires_booking');
END;

CREATE TABLE request_private (
  request_id TEXT PRIMARY KEY REFERENCES repair_requests(id) ON DELETE CASCADE,
  contact_email TEXT NOT NULL CHECK (contact_email LIKE '%_@_%' AND length(contact_email) <= 254),
  contact_phone TEXT NOT NULL CHECK (length(contact_phone) BETWEEN 7 AND 32),
  street_address TEXT CHECK (street_address IS NULL OR length(street_address) <= 200),
  address_city TEXT CHECK (address_city IS NULL OR length(address_city) <= 80),
  address_state TEXT CHECK (address_state IS NULL OR length(address_state) <= 2),
  location_notes TEXT CHECK (location_notes IS NULL OR length(location_notes) <= 300),
  consent_snapshot_json TEXT NOT NULL CHECK (json_valid(consent_snapshot_json))
) STRICT;

CREATE TABLE request_media (
  file_id TEXT PRIMARY KEY REFERENCES files(id) ON DELETE CASCADE,
  request_id TEXT NOT NULL REFERENCES repair_requests(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('photo', 'video')),
  -- only sanitized photos may be shown to matched mechanics before a confirmed booking
  shareable_before_booking INTEGER NOT NULL CHECK (shareable_before_booking IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (kind = 'photo' OR shareable_before_booking = 0)
) STRICT;
CREATE INDEX request_media_request_idx ON request_media(request_id);

-- ---------------------------------------------------------------------------------
-- Matching: every evaluated mechanic is recorded (eligible or not, with reason codes)
-- so admins can diagnose empty results; notified mechanics get a job_matches row.
-- ---------------------------------------------------------------------------------

CREATE TABLE match_evaluations (
  request_id TEXT NOT NULL REFERENCES repair_requests(id) ON DELETE CASCADE,
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id) ON DELETE CASCADE,
  eligible INTEGER NOT NULL CHECK (eligible IN (0, 1)),
  notified INTEGER NOT NULL DEFAULT 0 CHECK (notified IN (0, 1)),
  distance_miles REAL CHECK (distance_miles IS NULL OR distance_miles >= 0),
  reasons_json TEXT NOT NULL CHECK (json_valid(reasons_json) AND json_type(reasons_json) = 'array'),
  evaluated_at TEXT NOT NULL,
  PRIMARY KEY (request_id, mechanic_id),
  CHECK (notified = 0 OR eligible = 1)
) STRICT;

CREATE TABLE job_matches (
  id TEXT PRIMARY KEY,
  request_id TEXT NOT NULL REFERENCES repair_requests(id) ON DELETE CASCADE,
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id) ON DELETE CASCADE,
  distance_miles REAL NOT NULL CHECK (distance_miles >= 0),
  rank INTEGER NOT NULL CHECK (rank >= 1),
  status TEXT NOT NULL DEFAULT 'notified'
    CHECK (status IN ('notified', 'interested', 'quoted', 'passed')),
  notified_at TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (request_id, mechanic_id)
) STRICT;
CREATE INDEX job_matches_mechanic_idx ON job_matches(mechanic_id, notified_at);

-- ---------------------------------------------------------------------------------
-- Quotes. Prices are computed on the server from quote_items; both are immutable
-- once written (a mechanic withdraws and re-quotes instead of editing).
-- ---------------------------------------------------------------------------------

CREATE TABLE quotes (
  id TEXT PRIMARY KEY,
  request_id TEXT NOT NULL REFERENCES repair_requests(id) ON DELETE CASCADE,
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id),
  status TEXT NOT NULL DEFAULT 'submitted'
    CHECK (status IN ('submitted', 'withdrawn', 'expired', 'selected', 'declined')),
  service_mode TEXT NOT NULL CHECK (service_mode IN ('mobile', 'garage')),
  parts_included INTEGER NOT NULL CHECK (parts_included IN (0, 1)),
  currency TEXT NOT NULL DEFAULT 'USD' CHECK (currency = 'USD'),
  labor_cents INTEGER NOT NULL CHECK (labor_cents >= 0),
  parts_cents INTEGER NOT NULL CHECK (parts_cents >= 0),
  tax_cents INTEGER NOT NULL CHECK (tax_cents >= 0),
  fee_cents INTEGER NOT NULL CHECK (fee_cents >= 0),
  total_cents INTEGER NOT NULL
    CHECK (total_cents = labor_cents + parts_cents + tax_cents + fee_cents AND total_cents > 0),
  slot_start_at TEXT NOT NULL,
  slot_end_at TEXT NOT NULL,
  estimated_duration_minutes INTEGER NOT NULL CHECK (estimated_duration_minutes BETWEEN 15 AND 1440),
  scope TEXT NOT NULL CHECK (length(trim(scope)) BETWEEN 3 AND 1000),
  exclusions TEXT CHECK (exclusions IS NULL OR length(exclusions) <= 1000),
  notes TEXT CHECK (notes IS NULL OR length(notes) <= 1000),
  expires_at TEXT NOT NULL,
  withdrawn_at TEXT,
  is_demo_fixture INTEGER NOT NULL DEFAULT 0 CHECK (is_demo_fixture IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (slot_end_at > slot_start_at),
  CHECK (expires_at <= slot_start_at)
) STRICT;
-- one active quote per mechanic per request
CREATE UNIQUE INDEX quotes_one_active_per_mechanic
  ON quotes(request_id, mechanic_id) WHERE status IN ('submitted', 'selected');
CREATE INDEX quotes_request_idx ON quotes(request_id);
CREATE INDEX quotes_mechanic_slot_idx ON quotes(mechanic_id, slot_start_at);

-- A submitted quote commits the offered slot until it expires: the same mechanic may
-- not offer an overlapping slot in another active quote or over an active booking.
-- Application code expires stale quotes (using its injected clock) before inserting.
CREATE TRIGGER quotes_no_overlapping_slot
BEFORE INSERT ON quotes
WHEN NEW.status = 'submitted'
BEGIN
  SELECT RAISE(ABORT, 'slot_conflict')
  WHERE EXISTS (
      SELECT 1 FROM quotes q
      WHERE q.mechanic_id = NEW.mechanic_id
        AND q.status IN ('submitted', 'selected')
        AND q.slot_start_at < NEW.slot_end_at
        AND NEW.slot_start_at < q.slot_end_at
    )
    OR EXISTS (
      SELECT 1 FROM bookings b
      WHERE b.mechanic_id = NEW.mechanic_id
        AND b.status IN ('pending_payment', 'confirmed', 'in_progress')
        AND b.slot_start_at < NEW.slot_end_at
        AND NEW.slot_start_at < b.slot_end_at
    );
END;

CREATE TRIGGER quotes_valid_status_transition
BEFORE UPDATE OF status ON quotes
WHEN NEW.status IS NOT OLD.status
  AND (OLD.status || '>' || NEW.status) NOT IN (
    'submitted>withdrawn', 'submitted>expired', 'submitted>selected', 'submitted>declined',
    'selected>declined'
  )
BEGIN
  SELECT RAISE(ABORT, 'invalid_quote_transition');
END;

CREATE TRIGGER quotes_terms_are_immutable
BEFORE UPDATE ON quotes
WHEN NEW.request_id IS NOT OLD.request_id
  OR NEW.mechanic_id IS NOT OLD.mechanic_id
  OR NEW.service_mode IS NOT OLD.service_mode
  OR NEW.parts_included IS NOT OLD.parts_included
  OR NEW.currency IS NOT OLD.currency
  OR NEW.labor_cents IS NOT OLD.labor_cents
  OR NEW.parts_cents IS NOT OLD.parts_cents
  OR NEW.tax_cents IS NOT OLD.tax_cents
  OR NEW.fee_cents IS NOT OLD.fee_cents
  OR NEW.total_cents IS NOT OLD.total_cents
  OR NEW.slot_start_at IS NOT OLD.slot_start_at
  OR NEW.slot_end_at IS NOT OLD.slot_end_at
  OR NEW.estimated_duration_minutes IS NOT OLD.estimated_duration_minutes
  OR NEW.scope IS NOT OLD.scope
  OR NEW.exclusions IS NOT OLD.exclusions
  OR NEW.notes IS NOT OLD.notes
  OR NEW.expires_at IS NOT OLD.expires_at
  OR NEW.is_demo_fixture IS NOT OLD.is_demo_fixture
BEGIN
  SELECT RAISE(ABORT, 'quote_terms_immutable');
END;

CREATE TABLE quote_items (
  id TEXT PRIMARY KEY,
  quote_id TEXT NOT NULL REFERENCES quotes(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('labor', 'part', 'tax', 'fee')),
  description TEXT NOT NULL CHECK (length(trim(description)) BETWEEN 1 AND 200),
  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 100),
  unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents BETWEEN 0 AND 10000000),
  amount_cents INTEGER NOT NULL CHECK (amount_cents = quantity * unit_price_cents),
  sort_order INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE INDEX quote_items_quote_idx ON quote_items(quote_id, sort_order);

CREATE TRIGGER quote_items_are_immutable
BEFORE UPDATE ON quote_items
BEGIN
  SELECT RAISE(ABORT, 'quote_items_immutable');
END;

-- ---------------------------------------------------------------------------------
-- Bookings ("reservations" while pending payment). One per request, one per quote.
-- New bookings always start as pending_payment; with Stripe not connected nothing can
-- move them to confirmed. Only clearly flagged demo fixtures are inserted confirmed.
-- ---------------------------------------------------------------------------------

CREATE TABLE bookings (
  id TEXT PRIMARY KEY,
  request_id TEXT NOT NULL UNIQUE REFERENCES repair_requests(id),
  quote_id TEXT NOT NULL UNIQUE REFERENCES quotes(id),
  customer_id TEXT NOT NULL REFERENCES users(id),
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id),
  status TEXT NOT NULL DEFAULT 'pending_payment'
    CHECK (status IN ('pending_payment', 'confirmed', 'in_progress', 'completed', 'cancelled', 'disputed')),
  payment_state TEXT NOT NULL DEFAULT 'stripe_not_connected'
    CHECK (payment_state IN ('stripe_not_connected', 'demo_fixture_no_real_payment')),
  payout_status TEXT NOT NULL DEFAULT 'not_eligible'
    CHECK (payout_status IN ('not_eligible', 'pending', 'sent', 'failed', 'held')),
  service_mode TEXT NOT NULL CHECK (service_mode IN ('mobile', 'garage')),
  slot_start_at TEXT NOT NULL,
  slot_end_at TEXT NOT NULL,
  currency TEXT NOT NULL CHECK (currency = 'USD'),
  labor_cents INTEGER NOT NULL CHECK (labor_cents >= 0),
  parts_cents INTEGER NOT NULL CHECK (parts_cents >= 0),
  tax_cents INTEGER NOT NULL CHECK (tax_cents >= 0),
  fee_cents INTEGER NOT NULL CHECK (fee_cents >= 0),
  total_cents INTEGER NOT NULL CHECK (total_cents = labor_cents + parts_cents + tax_cents + fee_cents),
  platform_fee_bps INTEGER NOT NULL CHECK (platform_fee_bps BETWEEN 0 AND 3000),
  -- platform fee = labor * bps / 10000, rounded half up (integer math)
  platform_fee_cents INTEGER NOT NULL
    CHECK (platform_fee_cents = (labor_cents * platform_fee_bps + 5000) / 10000),
  mechanic_payout_cents INTEGER NOT NULL
    CHECK (mechanic_payout_cents = total_cents - platform_fee_cents),
  quote_snapshot_json TEXT NOT NULL CHECK (json_valid(quote_snapshot_json)),
  consent_snapshot_json TEXT NOT NULL CHECK (json_valid(consent_snapshot_json)),
  is_demo_fixture INTEGER NOT NULL DEFAULT 0 CHECK (is_demo_fixture IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  confirmed_at TEXT,
  started_at TEXT,
  completed_at TEXT,
  cancelled_at TEXT,
  cancel_reason TEXT CHECK (cancel_reason IS NULL OR length(cancel_reason) <= 500),
  CHECK (slot_end_at > slot_start_at),
  CHECK ((is_demo_fixture = 1) = (payment_state = 'demo_fixture_no_real_payment')),
  CHECK (is_demo_fixture = 1 OR payout_status = 'not_eligible')
) STRICT;
CREATE INDEX bookings_customer_idx ON bookings(customer_id, created_at);
CREATE INDEX bookings_mechanic_idx ON bookings(mechanic_id, slot_start_at);

-- Real (non-fixture) bookings can only be created as pending_payment.
CREATE TRIGGER bookings_insert_requires_pending_payment
BEFORE INSERT ON bookings
WHEN NEW.is_demo_fixture = 0 AND NEW.status IS NOT 'pending_payment'
BEGIN
  SELECT RAISE(ABORT, 'booking_must_start_pending_payment');
END;

-- The booking must match its quote exactly: same request, mechanic, customer, slot,
-- mode and server-computed money. The browser never supplies an amount.
CREATE TRIGGER bookings_insert_matches_quote
BEFORE INSERT ON bookings
WHEN NOT EXISTS (
  SELECT 1
  FROM quotes q
  JOIN repair_requests r ON r.id = q.request_id
  WHERE q.id = NEW.quote_id
    AND q.request_id = NEW.request_id
    AND q.mechanic_id = NEW.mechanic_id
    AND r.customer_id = NEW.customer_id
    AND q.service_mode = NEW.service_mode
    AND q.slot_start_at = NEW.slot_start_at
    AND q.slot_end_at = NEW.slot_end_at
    AND q.currency = NEW.currency
    AND q.labor_cents = NEW.labor_cents
    AND q.parts_cents = NEW.parts_cents
    AND q.tax_cents = NEW.tax_cents
    AND q.fee_cents = NEW.fee_cents
    AND q.total_cents = NEW.total_cents
)
BEGIN
  SELECT RAISE(ABORT, 'booking_does_not_match_quote');
END;

CREATE TRIGGER bookings_valid_status_transition
BEFORE UPDATE OF status ON bookings
WHEN NEW.status IS NOT OLD.status
  AND (OLD.status || '>' || NEW.status) NOT IN (
    'pending_payment>cancelled',
    'confirmed>in_progress', 'confirmed>cancelled', 'confirmed>disputed',
    'in_progress>completed', 'in_progress>cancelled', 'in_progress>disputed',
    'completed>disputed'
  )
BEGIN
  SELECT RAISE(ABORT, 'invalid_booking_transition');
END;

-- Stripe is not connected: nothing may move a reservation past pending_payment
-- except cancellation. (The payments phase will replace this with a verified-webhook path.)
-- Created after bookings_valid_status_transition on purpose: SQLite fires the most
-- recently created trigger first, so this specific message is the one reported.
CREATE TRIGGER bookings_payment_not_connected
BEFORE UPDATE OF status ON bookings
WHEN OLD.status = 'pending_payment' AND NEW.status NOT IN ('pending_payment', 'cancelled')
BEGIN
  SELECT RAISE(ABORT, 'payment_not_connected');
END;

CREATE TRIGGER bookings_snapshot_is_immutable
BEFORE UPDATE ON bookings
WHEN NEW.request_id IS NOT OLD.request_id
  OR NEW.quote_id IS NOT OLD.quote_id
  OR NEW.customer_id IS NOT OLD.customer_id
  OR NEW.mechanic_id IS NOT OLD.mechanic_id
  OR NEW.service_mode IS NOT OLD.service_mode
  OR NEW.slot_start_at IS NOT OLD.slot_start_at
  OR NEW.slot_end_at IS NOT OLD.slot_end_at
  OR NEW.currency IS NOT OLD.currency
  OR NEW.labor_cents IS NOT OLD.labor_cents
  OR NEW.parts_cents IS NOT OLD.parts_cents
  OR NEW.tax_cents IS NOT OLD.tax_cents
  OR NEW.fee_cents IS NOT OLD.fee_cents
  OR NEW.total_cents IS NOT OLD.total_cents
  OR NEW.platform_fee_bps IS NOT OLD.platform_fee_bps
  OR NEW.platform_fee_cents IS NOT OLD.platform_fee_cents
  OR NEW.mechanic_payout_cents IS NOT OLD.mechanic_payout_cents
  OR NEW.quote_snapshot_json IS NOT OLD.quote_snapshot_json
  OR NEW.consent_snapshot_json IS NOT OLD.consent_snapshot_json
  OR NEW.is_demo_fixture IS NOT OLD.is_demo_fixture
  OR NEW.payment_state IS NOT OLD.payment_state
  OR NEW.created_at IS NOT OLD.created_at
BEGIN
  SELECT RAISE(ABORT, 'booking_snapshot_immutable');
END;

-- Payout state is only meaningful for demo fixtures until Stripe Connect exists.
CREATE TRIGGER bookings_payout_requires_fixture
BEFORE UPDATE OF payout_status ON bookings
WHEN NEW.payout_status IS NOT OLD.payout_status AND OLD.is_demo_fixture = 0
BEGIN
  SELECT RAISE(ABORT, 'payout_not_connected');
END;

-- ---------------------------------------------------------------------------------
-- Post-booking records (only reachable for confirmed bookings, i.e. demo fixtures now)
-- ---------------------------------------------------------------------------------

CREATE TABLE change_orders (
  id TEXT PRIMARY KEY,
  booking_id TEXT NOT NULL REFERENCES bookings(id),
  proposed_by TEXT NOT NULL REFERENCES users(id),
  description TEXT NOT NULL CHECK (length(trim(description)) BETWEEN 3 AND 1000),
  reason TEXT NOT NULL CHECK (length(trim(reason)) BETWEEN 3 AND 1000),
  currency TEXT NOT NULL DEFAULT 'USD' CHECK (currency = 'USD'),
  labor_cents INTEGER NOT NULL DEFAULT 0 CHECK (labor_cents >= 0),
  parts_cents INTEGER NOT NULL DEFAULT 0 CHECK (parts_cents >= 0),
  tax_cents INTEGER NOT NULL DEFAULT 0 CHECK (tax_cents >= 0),
  amount_cents INTEGER NOT NULL
    CHECK (amount_cents = labor_cents + parts_cents + tax_cents AND amount_cents > 0),
  status TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'approved', 'rejected', 'void')),
  payment_state TEXT NOT NULL DEFAULT 'stripe_not_connected'
    CHECK (payment_state IN ('stripe_not_connected', 'demo_fixture_no_real_payment')),
  decided_by TEXT REFERENCES users(id),
  decided_at TEXT,
  decision_note TEXT CHECK (decision_note IS NULL OR length(decision_note) <= 500),
  is_demo_fixture INTEGER NOT NULL DEFAULT 0 CHECK (is_demo_fixture IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (status = 'proposed' OR (decided_at IS NOT NULL))
) STRICT;
CREATE INDEX change_orders_booking_idx ON change_orders(booking_id);

CREATE TRIGGER change_orders_require_active_booking
BEFORE INSERT ON change_orders
WHEN NOT EXISTS (
  SELECT 1 FROM bookings b
  WHERE b.id = NEW.booking_id AND b.status IN ('confirmed', 'in_progress')
)
BEGIN
  SELECT RAISE(ABORT, 'change_order_requires_active_booking');
END;

CREATE TRIGGER change_orders_valid_status_transition
BEFORE UPDATE OF status ON change_orders
WHEN NEW.status IS NOT OLD.status
  AND (OLD.status || '>' || NEW.status) NOT IN (
    'proposed>approved', 'proposed>rejected', 'proposed>void', 'approved>void'
  )
BEGIN
  SELECT RAISE(ABORT, 'invalid_change_order_transition');
END;

CREATE TRIGGER change_orders_terms_are_immutable
BEFORE UPDATE ON change_orders
WHEN NEW.booking_id IS NOT OLD.booking_id
  OR NEW.proposed_by IS NOT OLD.proposed_by
  OR NEW.description IS NOT OLD.description
  OR NEW.reason IS NOT OLD.reason
  OR NEW.currency IS NOT OLD.currency
  OR NEW.labor_cents IS NOT OLD.labor_cents
  OR NEW.parts_cents IS NOT OLD.parts_cents
  OR NEW.tax_cents IS NOT OLD.tax_cents
  OR NEW.amount_cents IS NOT OLD.amount_cents
  OR NEW.is_demo_fixture IS NOT OLD.is_demo_fixture
BEGIN
  SELECT RAISE(ABORT, 'change_order_terms_immutable');
END;

CREATE TABLE invoices (
  id TEXT PRIMARY KEY,
  booking_id TEXT NOT NULL UNIQUE REFERENCES bookings(id),
  invoice_number TEXT NOT NULL UNIQUE,
  currency TEXT NOT NULL CHECK (currency = 'USD'),
  line_items_json TEXT NOT NULL CHECK (json_valid(line_items_json) AND json_type(line_items_json) = 'array'),
  labor_cents INTEGER NOT NULL CHECK (labor_cents >= 0),
  parts_cents INTEGER NOT NULL CHECK (parts_cents >= 0),
  tax_cents INTEGER NOT NULL CHECK (tax_cents >= 0),
  fee_cents INTEGER NOT NULL CHECK (fee_cents >= 0),
  total_cents INTEGER NOT NULL CHECK (total_cents = labor_cents + parts_cents + tax_cents + fee_cents),
  platform_fee_bps INTEGER NOT NULL CHECK (platform_fee_bps BETWEEN 0 AND 3000),
  platform_fee_cents INTEGER NOT NULL
    CHECK (platform_fee_cents = (labor_cents * platform_fee_bps + 5000) / 10000),
  mechanic_payout_cents INTEGER NOT NULL CHECK (mechanic_payout_cents = total_cents - platform_fee_cents),
  approved_change_order_count INTEGER NOT NULL DEFAULT 0 CHECK (approved_change_order_count >= 0),
  notes TEXT CHECK (notes IS NULL OR length(notes) <= 1000),
  issued_by TEXT NOT NULL REFERENCES users(id),
  issued_at TEXT NOT NULL,
  is_demo_fixture INTEGER NOT NULL DEFAULT 0 CHECK (is_demo_fixture IN (0, 1))
) STRICT;

CREATE TRIGGER invoices_are_immutable
BEFORE UPDATE ON invoices
BEGIN
  SELECT RAISE(ABORT, 'invoice_immutable');
END;

CREATE TRIGGER invoices_require_completed_booking
BEFORE INSERT ON invoices
WHEN NOT EXISTS (
  SELECT 1 FROM bookings b
  WHERE b.id = NEW.booking_id AND b.status IN ('completed', 'disputed')
    AND b.is_demo_fixture = NEW.is_demo_fixture
)
BEGIN
  SELECT RAISE(ABORT, 'invoice_requires_completed_booking');
END;

CREATE TABLE reviews (
  id TEXT PRIMARY KEY,
  booking_id TEXT NOT NULL UNIQUE REFERENCES bookings(id),
  customer_id TEXT NOT NULL REFERENCES users(id),
  mechanic_id TEXT NOT NULL REFERENCES mechanic_profiles(user_id),
  rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment TEXT CHECK (comment IS NULL OR length(comment) <= 1000),
  -- reviews of demo-fixture bookings are fixtures too and never count toward ratings
  is_demo_fixture INTEGER NOT NULL DEFAULT 0 CHECK (is_demo_fixture IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX reviews_mechanic_idx ON reviews(mechanic_id);

CREATE TRIGGER reviews_require_completed_booking_by_customer
BEFORE INSERT ON reviews
WHEN NOT EXISTS (
  SELECT 1 FROM bookings b
  WHERE b.id = NEW.booking_id
    AND b.status = 'completed'
    AND b.customer_id = NEW.customer_id
    AND b.mechanic_id = NEW.mechanic_id
    AND b.is_demo_fixture = NEW.is_demo_fixture
)
BEGIN
  SELECT RAISE(ABORT, 'review_requires_completed_booking');
END;

-- ---------------------------------------------------------------------------------
-- Notifications, local email capture and audit trail
-- ---------------------------------------------------------------------------------

CREATE TABLE notifications (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type TEXT NOT NULL CHECK (length(type) BETWEEN 1 AND 60),
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 140),
  body TEXT NOT NULL CHECK (length(body) <= 1000),
  link_path TEXT CHECK (link_path IS NULL OR (link_path GLOB '/*' AND link_path NOT GLOB '//*')),
  read_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX notifications_user_idx ON notifications(user_id, created_at);

-- Development email capture: messages are stored here and shown in the admin
-- "Dev mailbox". Nothing is sent over the network.
CREATE TABLE email_outbox (
  id TEXT PRIMARY KEY,
  to_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  to_email TEXT NOT NULL,
  subject TEXT NOT NULL CHECK (length(subject) BETWEEN 1 AND 200),
  body_text TEXT NOT NULL CHECK (length(body_text) <= 5000),
  template TEXT NOT NULL,
  delivery TEXT NOT NULL DEFAULT 'captured_locally' CHECK (delivery = 'captured_locally'),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX email_outbox_created_idx ON email_outbox(created_at);

CREATE TABLE audit_events (
  id TEXT PRIMARY KEY,
  actor_user_id TEXT REFERENCES users(id),
  actor_role TEXT NOT NULL CHECK (actor_role IN ('customer', 'mechanic', 'admin', 'system')),
  action TEXT NOT NULL CHECK (length(action) BETWEEN 1 AND 80),
  entity_type TEXT NOT NULL CHECK (length(entity_type) BETWEEN 1 AND 40),
  entity_id TEXT,
  reason TEXT CHECK (reason IS NULL OR length(reason) <= 500),
  metadata_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata_json)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;
CREATE INDEX audit_events_created_idx ON audit_events(created_at);
CREATE INDEX audit_events_entity_idx ON audit_events(entity_type, entity_id);

CREATE TRIGGER audit_events_append_only_update
BEFORE UPDATE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit_append_only');
END;

CREATE TRIGGER audit_events_append_only_delete
BEFORE DELETE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit_append_only');
END;

